CREATE FUNCTION public.save_quotation(_request jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE b uuid:=(_request->>'businessId')::uuid;i uuid:=(_request->>'id')::uuid;br uuid:=(_request->>'branchId')::uuid;p uuid:=(_request->>'partyId')::uuid;q public.quotations;c public.parties;l jsonb;v public.product_variants;product public.products;rows jsonb:='[]';qty numeric;price numeric;discount numeric;rate numeric;base numeric;tax numeric;total numeric:=0;
BEGIN
IF NOT public.has_business_role(b,'staff') OR NOT public.can_access_branch(b,br) THEN RAISE EXCEPTION 'Quotation access denied';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(b::text,0));SELECT * INTO q FROM public.quotations WHERE id=i FOR UPDATE;
IF FOUND THEN IF q.business_id<>b OR NOT public.can_access_branch(b,q.branch_id) THEN RAISE EXCEPTION 'Quotation access denied';END IF;IF q.request=_request THEN RETURN i;END IF;IF q.status='converted' THEN RAISE EXCEPTION 'Converted quotation is locked';END IF;IF q.revision<>coalesce((_request->>'revision')::integer,0) THEN RAISE EXCEPTION 'Quotation changed; reload';END IF;ELSE IF coalesce((_request->>'revision')::integer,0)<>0 THEN RAISE EXCEPTION 'Quotation not found';END IF;END IF;
SELECT * INTO c FROM public.parties WHERE id=p AND business_id=b AND kind='customer' AND is_active;IF NOT FOUND THEN RAISE EXCEPTION 'Active customer required';END IF;
IF coalesce(_request->>'status','') NOT IN ('draft','sent','accepted','declined') OR coalesce(length(btrim(_request->>'reference')),0) NOT BETWEEN 1 AND 200 OR jsonb_typeof(_request->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(_request->'lines') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid quotation';END IF;
FOR l IN SELECT value FROM jsonb_array_elements(_request->'lines') LOOP
SELECT * INTO v FROM public.product_variants WHERE business_id=b AND id=(l->>'variantId')::uuid AND is_active;IF NOT FOUND THEN RAISE EXCEPTION 'Active item required';END IF;SELECT * INTO product FROM public.products WHERE business_id=b AND id=v.product_id AND is_active;IF NOT FOUND THEN RAISE EXCEPTION 'Active product required';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>'variantId'=v.id::text) THEN RAISE EXCEPTION 'Combine duplicate items';END IF;
qty:=(l->>'quantity')::numeric;price:=(l->>'price')::numeric;discount:=(l->>'discount')::numeric;rate:=(l->>'taxRate')::numeric;
IF qty IS NULL OR price IS NULL OR discount IS NULL OR rate IS NULL OR qty<=0 OR qty>999999 OR price<0 OR price>999999999 OR discount<0 OR discount>999999999 OR rate<0 OR rate>100 OR qty<>round(qty,3) OR price<>round(price,2) OR discount<>round(discount,2) OR rate<>round(rate,2) OR qty::text IN ('NaN','Infinity','-Infinity') OR price::text IN ('NaN','Infinity','-Infinity') OR discount::text IN ('NaN','Infinity','-Infinity') OR rate::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Invalid quotation amounts';END IF;
base:=round(qty*price,2)-discount;IF base<0 THEN RAISE EXCEPTION 'Discount exceeds line';END IF;tax:=round(base*rate/100,2);total:=total+base+tax;rows:=rows||jsonb_build_array(l||jsonb_build_object('name',product.name||' · '||v.name,'sku',v.sku,'total',base+tax));END LOOP;
INSERT INTO public.quotations(id,business_id,branch_id,party_id,reference,quotation_date,expires_on,status,customer,lines,total,request,actor_id) VALUES(i,b,br,p,btrim(_request->>'reference'),(_request->>'date')::date,(_request->>'expiresOn')::date,_request->>'status',jsonb_build_object('name',c.name,'phone',coalesce(nullif(btrim(_request->>'mobile'),''),c.phone),'address',c.address,'pan',c.pan_vat_number),rows,total,_request,auth.uid()) ON CONFLICT(id) DO UPDATE SET branch_id=EXCLUDED.branch_id,party_id=EXCLUDED.party_id,reference=EXCLUDED.reference,quotation_date=EXCLUDED.quotation_date,expires_on=EXCLUDED.expires_on,status=EXCLUDED.status,customer=EXCLUDED.customer,lines=EXCLUDED.lines,total=EXCLUDED.total,request=EXCLUDED.request,revision=quotations.revision+1,updated_at=now();RETURN i;END $$;
REVOKE ALL ON FUNCTION public.save_quotation(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_quotation(jsonb) TO authenticated;
CREATE FUNCTION public.guard_quotation_sale() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quotations;l jsonb;expected jsonb;enriched jsonb:='[]';BEGIN
IF NEW.request->>'quotationId' IS NULL THEN IF NEW.quotation_id IS NOT NULL THEN RAISE EXCEPTION 'Quotation request required';END IF;RETURN NEW;END IF;SELECT * INTO q FROM public.quotations WHERE id=(NEW.request->>'quotationId')::uuid AND business_id=NEW.business_id;
IF NOT FOUND OR q.sale_id IS NULL OR q.branch_id<>NEW.branch_id OR q.party_id IS DISTINCT FROM NEW.party_id OR NEW.kind<>'sale' OR (NEW.status='draft' AND NEW.id<>q.sale_id) OR NEW.source_id IS NOT NULL THEN RAISE EXCEPTION 'Invalid quotation sale link';END IF;
IF jsonb_array_length(NEW.lines)<>jsonb_array_length(q.lines) THEN RAISE EXCEPTION 'Quotation items must be preserved';END IF;
FOR l IN SELECT value FROM jsonb_array_elements(NEW.lines) LOOP SELECT r INTO expected FROM jsonb_array_elements(q.lines) r WHERE r->>'variantId'=l->>'variantId';IF expected IS NULL OR (l->>'quantity')::numeric<>(expected->>'quantity')::numeric OR (l->>'price')::numeric<>(expected->>'price')::numeric OR (l->>'discount')::numeric<>(expected->>'discount')::numeric OR (l->>'taxRate')::numeric<>(expected->>'taxRate')::numeric THEN RAISE EXCEPTION 'Quotation pricing must be preserved';END IF;enriched:=enriched||jsonb_build_array(l||jsonb_build_object('name',expected->>'name','sku',expected->>'sku'));END LOOP;
IF NEW.total<>q.total THEN RAISE EXCEPTION 'Quotation total must be preserved';END IF;IF NEW.status='confirmed' AND public.normalize_member_mobile(NEW.request->>'mobile') IS DISTINCT FROM public.normalize_member_mobile(q.customer->>'phone') THEN RAISE EXCEPTION 'Quotation customer mobile must be preserved';END IF;
NEW.lines:=enriched;NEW.quotation_id:=q.id;RETURN NEW;END $$;
CREATE TRIGGER quotation_sale_guard BEFORE INSERT ON public.commerce_documents FOR EACH ROW EXECUTE FUNCTION public.guard_quotation_sale();REVOKE ALL ON FUNCTION public.guard_quotation_sale() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.convert_quotation(_business uuid,_id uuid,_period uuid,_date date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quotations;i uuid:=gen_random_uuid();req jsonb;BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(_business::text,0));SELECT * INTO q FROM public.quotations WHERE id=_id AND business_id=_business FOR UPDATE;
IF NOT FOUND OR NOT public.has_business_role(_business,'staff') OR NOT public.can_access_branch(_business,q.branch_id) THEN RAISE EXCEPTION 'Quotation access denied';END IF;IF q.sale_id IS NOT NULL THEN RETURN q.sale_id;END IF;IF q.status='declined' OR (q.expires_on IS NOT NULL AND q.expires_on<_date) THEN RAISE EXCEPTION 'Quotation declined or expired';END IF;IF public.normalize_member_mobile(q.customer->>'phone') IS NULL THEN RAISE EXCEPTION 'Valid customer mobile required before conversion';END IF;
UPDATE public.quotations SET sale_id=i,status='converted',revision=revision+1,updated_at=now() WHERE id=q.id;
req:=jsonb_build_object('id',i,'businessId',_business,'branchId',q.branch_id,'periodId',_period,'date',_date,'kind','sale','status','draft','sourceId',NULL,'partyId',q.party_id,'mobile',q.customer->>'phone','reference','INV-Q-'||q.id::text,'quotationId',q.id,'lines',q.lines,'payments','[]'::jsonb,'customerSnapshot',q.customer);PERFORM public.post_commerce_document(req);RETURN i;END $$;
REVOKE ALL ON FUNCTION public.convert_quotation(uuid,uuid,uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.convert_quotation(uuid,uuid,uuid,date) TO authenticated;